     9	// Run applies jobs sequentially and finalizes their accepted count.
    10	func Run(ctx context.Context, jobs []int, apply func(context.Context, int) error, finalize func(context.Context, int) error, finalizationBudget time.Duration) (accepted int, err error) {
    11		for _, job := range jobs {
    12			if ctxErr := ctx.Err(); ctxErr != nil {
    13				err = cancellationError(ctx)
    14				break
    15			}
    16			if applyErr := apply(ctx, job); applyErr != nil {
    17				err = applyErr
    18				if ctx.Err() != nil {
    19					err = errors.Join(err, cancellationError(ctx))
    20				}
    21				break
    22			}
    23			accepted++
    24		}
    25		if accepted != 0 {
    26			finalCtx, cancel := context.WithTimeout(context.Background(), finalizationBudget)
    27			finalErr := finalize(finalCtx, accepted)
    28			cancel()
    29			err = errors.Join(err, finalErr)
    30		}
    31		return accepted, err
    32	}
    33	
    34	func cancellationError(ctx context.Context) error {
    35		return errors.Join(ctx.Err(), context.Cause(ctx))
    36	}
