    14			applied = append(applied, job)
    15			return nil
    16		}, func(_ context.Context, count int) error {
    17			finalized = count
    18			return nil
    19		}, time.Second)
    20		if err != nil || n != 2 || finalized != 2 || len(applied) != 2 || applied[0] != 3 || applied[1] != 5 {
    21			t.Fatalf("accepted=%d finalized=%d applied=%v err=%v", n, finalized, applied, err)
    22		}
