    27	func TestInterruptedCommandFinalizesAcceptedReceipt(t *testing.T) {
    28		if runtime.GOOS == "windows" {
    29			t.Skip("os.Interrupt delivery to child processes is unsupported on Windows")
    30		}
    31		binary := buildCommand(t)
    32		receipt := filepath.Join(t.TempDir(), "receipt")
    33		cmd := exec.Command(binary, "--receipt", receipt, "1", "0")
    34		var stdout bytes.Buffer
    35		cmd.Stdout = &stdout
    36		stderr, err := cmd.StderrPipe()
    37		if err != nil {
    38			t.Fatal(err)
    39		}
    40		if err := cmd.Start(); err != nil {
    41			t.Fatal(err)
    42		}
    43		finished := false
    44		t.Cleanup(func() {
    45			if !finished && cmd.Process != nil {
    46				_ = cmd.Process.Kill()
    47				_ = cmd.Wait()
    48			}
    49		})
    50		lines := bufio.NewReader(stderr)
    51		type stderrResult struct {
    52			firstLine string
    53			rest      []byte
    54			err       error
    55		}
    56		type readyResult struct {
    57			firstLine string
    58			err       error
    59		}
    60		stderrDone := make(chan stderrResult, 1)
    61		ready := make(chan readyResult, 1)
    62		go func() {
    63			line, err := lines.ReadString('\n')
    64			if err == nil && strings.TrimSpace(line) != "waiting" {
    65				err = io.ErrUnexpectedEOF
    66			}
    67			ready <- readyResult{firstLine: line, err: err}
    68			rest, readErr := io.ReadAll(lines)
    69			if err == nil {
    70				err = readErr
    71			}
    72			stderrDone <- stderrResult{firstLine: line, rest: rest, err: err}
    73		}()
    74		select {
    75		case got := <-ready:
    76			if got.err != nil || strings.TrimSpace(got.firstLine) != "waiting" {
    77				t.Fatalf("waiting signal: line=%q err=%v", got.firstLine, got.err)
    78			}
    79		case <-time.After(5 * time.Second):
    80			t.Fatalf("command did not report waiting (stdout=%q)", stdout.String())
    81		}
    82		if err := cmd.Process.Signal(os.Interrupt); err != nil {
    83			t.Fatalf("interrupt command: %v", err)
    84		}
    85		waitErr := cmd.Wait()
    86		finished = true
    87		gotStderr := <-stderrDone
    88		if gotStderr.err != nil {
    89			t.Fatalf("read command stderr: %v", gotStderr.err)
    90		}
    91		if exit, ok := waitErr.(*exec.ExitError); !ok || exit.ExitCode() != 2 {
    92			t.Fatalf("command status=%v, want exit 2 (stdout=%q stderr=%q)", waitErr, stdout.String(), gotStderr.rest)
    93		}
    94		if got := stdout.String(); got != "accepted 1\n" {
    95			t.Errorf("stdout=%q, want accepted output", got)
    96		}
    97		if got := string(gotStderr.rest); !strings.Contains(got, "context canceled") {
    98			t.Errorf("stderr=%q, want cancellation diagnostic", got)
    99		}
